### 3. Funciones RPC y Concurrencia Transaccional (ACID)

La función RPC procesa la conversión de un pedido recurrente en una orden de venta en firme y genera la remisión WMS inicial, aplicando **bloqueo pesimista** (`SELECT FOR UPDATE`) sobre las existencias del inventario por lote para evitar condiciones de carrera (overselling en productos del mar de alta rotación).

```sql
CREATE OR REPLACE FUNCTION public.rpc_process_b2b_recurring_order_dispatch(
    p_recurring_order_id UUID,
    p_warehouse_id UUID
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
DECLARE
    v_tenant_id UUID;
    v_client_id UUID;
    v_branch_id UUID;
    v_order_id UUID;
    v_remission_id UUID;
    v_item RECORD;
    v_current_stock NUMERIC;
BEGIN
    -- 1. Obtener datos del pedido recurrente con bloqueo de cabecera
    SELECT tenant_id, client_id, branch_id
    INTO v_tenant_id, v_client_id, v_branch_id
    FROM b2b_recurring_orders
    WHERE id = p_recurring_order_id AND is_active = TRUE
    FOR UPDATE;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Pedido recurrente % no encontrado o inactivo.', p_recurring_order_id;
    END IF;

    -- 2. Crear la Orden de Venta en firme
    INSERT INTO sales_orders (
        tenant_id, client_id, branch_id, origin_channel, status, created_at
    ) VALUES (
        v_tenant_id, v_client_id, v_branch_id, 'B2B_PORTAL', 'CONFIRMED', NOW()
    ) RETURNING id INTO v_order_id;

    -- 3. Crear la Remisión WMS asociada
    INSERT INTO wms_dispatch_remissions (
        tenant_id, client_id, branch_id, sales_order_id, status, dispatched_at
    ) VALUES (
        v_tenant_id, v_client_id, v_branch_id, v_order_id, 'PENDING_PICKING', NOW()
    ) RETURNING id INTO v_remission_id;

    -- 4. Iterar sobre los ítems recurrentes, validar inventario con SELECT FOR UPDATE y descontar stock WMS
    FOR v_item IN 
        SELECT product_id, quantity_requested, unit_price 
        FROM b2b_recurring_order_items 
        WHERE recurring_order_id = p_recurring_order_id
    LOOP
        -- Bloqueo pesimista del inventario por almacén y producto
        SELECT available_quantity 
        INTO v_current_stock
        FROM wms_inventory_stock
        WHERE warehouse_id = p_warehouse_id AND product_id = v_item.product_id
        FOR UPDATE;

        IF NOT FOUND OR v_current_stock < v_item.quantity_requested THEN
            RAISE EXCEPTION 'Stock insuficiente para el producto % en el almacén %. Solicitado: %, Disponible: %', 
                v_item.product_id, p_warehouse_id, v_item.quantity_requested, COALESCE(v_current_stock, 0);
        END IF;

        -- Actualizar inventario WMS (Separación de stock)
        UPDATE wms_inventory_stock
        SET available_quantity = available_quantity - v_item.quantity_requested,
            allocated_quantity = allocated_quantity + v_item.quantity_requested,
            updated_at = NOW()
        WHERE warehouse_id = p_warehouse_id AND product_id = v_item.product_id;

        -- Insertar ítem en la orden de venta
        INSERT INTO sales_order_items (
            sales_order_id, product_id, quantity, unit_price
        ) VALUES (
            v_order_id, v_item.product_id, v_item.quantity_requested, v_item.unit_price
        );

        -- Insertar ítem en la remisión WMS
        INSERT INTO wms_dispatch_remission_items (
            remission_id, product_id, quantity_allocated
        ) VALUES (
            v_remission_id, v_item.product_id, v_item.quantity_requested
        );
    END LOOP;

    -- 5. Actualizar fecha de última ejecución del pedido recurrente
    UPDATE b2b_recurring_orders
    SET last_executed_at = NOW()
    WHERE id = p_recurring_order_id;

    RETURN jsonb_build_object(
        'success', true,
        'sales_order_id', v_order_id,
        'remission_id', v_remission_id,
        'message', 'Pedido recurrente procesado exitosamente y stock separado en WMS.'
    );
END;
$$;
```

